'use client';

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import NotebookDeskVariant from './variant-notebook-desk.jsx';
import KaiwaFirstVariant from './variant-kaiwa-first.jsx';
import StampRallyVariant from './variant-stamp-rally.jsx';

const variants = [
  {
    name: 'Chat Desk',
    axis: 'Chat plus compact study status',
    Component: NotebookDeskVariant,
  },
  {
    name: 'Original Chat',
    axis: 'Large original-style conversation container',
    Component: KaiwaFirstVariant,
  },
  {
    name: 'Chat Rally',
    axis: 'Conversation milestones and topic switching',
    Component: StampRallyVariant,
  },
];

function getInitialVariant() {
  if (typeof window === 'undefined') return 0;
  const value = Number.parseInt(new URLSearchParams(window.location.search).get('v'), 10);
  if (Number.isNaN(value)) return 0;
  return Math.min(Math.max(value - 1, 0), variants.length - 1);
}

export default function MainPagePrototype() {
  const [current, setCurrent] = useState(getInitialVariant);
  const [mountKey, setMountKey] = useState(0);
  const [ready, setReady] = useState(false);
  const pickerRef = useRef(null);
  const highlightRef = useRef(null);
  const itemRefs = useRef([]);
  const ActiveVariant = variants[current].Component;

  const moveHighlight = useCallback(() => {
    const el = itemRefs.current[current];
    const highlight = highlightRef.current;
    if (!el || !highlight) return;
    highlight.style.width = `${el.offsetWidth}px`;
    highlight.style.transform = `translateX(${el.offsetLeft}px)`;
  }, [current]);

  useLayoutEffect(() => {
    moveHighlight();
  }, [moveHighlight, ready]);

  useEffect(() => {
    const firstFrame = requestAnimationFrame(() => {
      const secondFrame = requestAnimationFrame(() => setReady(true));
      return () => cancelAnimationFrame(secondFrame);
    });
    return () => cancelAnimationFrame(firstFrame);
  }, []);

  useEffect(() => {
    const handleResize = () => moveHighlight();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [moveHighlight]);

  useEffect(() => {
    function handleKeyDown(event) {
      if (/^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName) || event.target.isContentEditable) return;
      if (event.metaKey || event.ctrlKey || event.altKey) return;

      const num = Number.parseInt(event.key, 10);
      if (num >= 1 && num <= variants.length) setActive(num - 1);
      else if (event.key === 'ArrowRight') setActive((current + 1) % variants.length);
      else if (event.key === 'ArrowLeft') setActive((current - 1 + variants.length) % variants.length);
      else if (event.key === 'r' || event.key === 'R') replay();
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [current]);

  function setActive(index) {
    if (index < 0 || index >= variants.length) return;
    setCurrent(index);
    setMountKey((key) => key + 1);
    const url = new URL(window.location);
    url.searchParams.set('v', String(index + 1));
    window.history.replaceState(null, '', url);
  }

  function replay() {
    setMountKey((key) => key + 1);
  }

  return (
    <>
      <div key={`${current}-${mountKey}`} id="stage">
        <ActiveVariant />
      </div>

      <nav
        ref={pickerRef}
        className="proto-picker"
        aria-label="Prototype variants"
        data-ready={ready ? '' : undefined}
      >
        <span ref={highlightRef} className="proto-picker-highlight" aria-hidden="true"></span>
        {variants.map((variant, index) => (
          <button
            key={variant.name}
            ref={(node) => {
              itemRefs.current[index] = node;
            }}
            className="proto-picker-item"
            data-active={index === current ? '' : undefined}
            aria-current={index === current ? 'true' : undefined}
            onClick={() => setActive(index)}
          >
            {variant.name}
          </button>
        ))}
        <span className="proto-picker-divider" aria-hidden="true"></span>
        <button className="proto-picker-item proto-picker-replay" aria-label="Replay animation (R)" onClick={replay}>
          ↻
        </button>
      </nav>

      <style>{`
.proto-picker {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2147483647;
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 4px;
  border-radius: 999px;
  background: rgba(10, 10, 10, 0.82);
  -webkit-backdrop-filter: blur(12px) saturate(1.4);
  backdrop-filter: blur(12px) saturate(1.4);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.08) inset,
    0 8px 24px rgba(0, 0, 0, 0.24),
    0 2px 6px rgba(0, 0, 0, 0.12);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 13px;
  line-height: 1;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
}

.proto-picker-highlight {
  position: absolute;
  top: 4px;
  left: 0;
  height: 28px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  will-change: transform;
}

/* The slide is enabled only after first paint (data-ready), so load doesn't animate. */
.proto-picker[data-ready] .proto-picker-highlight {
  transition:
    transform 250ms cubic-bezier(0.23, 1, 0.32, 1),
    width 250ms cubic-bezier(0.23, 1, 0.32, 1);
}

@media (prefers-reduced-motion: reduce) {
  .proto-picker[data-ready] .proto-picker-highlight { transition: none; }
}

.proto-picker-item {
  position: relative; /* sits above the highlight */
  display: flex;
  align-items: center;
  height: 28px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(255, 255, 255, 0.55);
  font: inherit;
  cursor: pointer;
  transition: color 150ms ease-out;
}

.proto-picker-item:hover {
  color: rgba(255, 255, 255, 0.85);
}

.proto-picker-item:active {
  transform: scale(0.97);
}

.proto-picker-item:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.4);
  outline-offset: 2px;
}

.proto-picker-item[data-active] {
  color: #fff;
}

.proto-picker-divider {
  width: 1px;
  height: 16px;
  margin: 0 4px;
  background: rgba(255, 255, 255, 0.12);
}

.proto-picker-replay {
  padding: 0 10px;
  font-size: 14px;
}

.proto-picker[data-position="top"] {
  bottom: auto;
  top: 24px;
}
      `}</style>
    </>
  );
}
