import Link from 'next/link';

const messages = [
  ['assistant', '今日は助詞「で」と「に」を練習します。まず、「学校___勉強します」はどちらですか？'],
  ['user', '学校で勉強します。'],
  ['assistant', '正解です！「で」は動作が行われる場所に使います。次は「学校___行きます」は？'],
  ['user', '学校に行きます。'],
];

const cards = [
  ['N5 score', '72%', 'Particles need one more review', 'bg-mustard text-ink'],
  ['Today', 'で / に', 'Grammar focus from saved memory', 'bg-correction text-paper'],
  ['Provider', 'Local', 'Ollama-first conversation mode', 'bg-moss text-paper'],
];

export default function NotebookDeskVariant() {
  return (
    <main className="screen-shell pb-28">
      <section className="grid min-h-[calc(100vh-8rem)] items-center gap-6 py-6 xl:grid-cols-[0.78fr_1.22fr]">
        <div className="space-y-6 animate-panel-in">
          <div className="flex flex-wrap items-center gap-3">
            <img src="/icon.png" alt="" className="brutal-border h-20 w-20 rotate-[-8deg] object-cover shadow-shadow" />
            <Badge tone="mustard">Study desk</Badge>
            <Badge tone="moss">Local memory</Badge>
          </div>

          <div className="space-y-5">
            <p className="label-mono text-correction">Chat + dashboard hybrid</p>
            <h1 className="font-display text-5xl leading-[0.95] tracking-tight sm:text-7xl lg:text-8xl">
              Your next lesson is already open.
            </h1>
            <p className="max-w-2xl text-lg font-bold leading-8">
              This style keeps the original chat container but surrounds it with compact study status, so the homepage feels useful before the user clicks anything.
            </p>
          </div>

          <div className="flex flex-col gap-3 sm:flex-row xl:flex-col 2xl:flex-row">
            <CTA href="/dashboard" tone="primary">Start study session</CTA>
            <CTA href="/chat/sensei" tone="neutral">Continue chat</CTA>
          </div>
        </div>

        <div className="grid gap-4 lg:grid-cols-[0.8fr_1.2fr]">
          <aside className="grid gap-4">
            {cards.map(([label, value, body, tone]) => (
              <article key={label} className="brutal-border bg-white p-4 shadow-shadow">
                <span className={`brutal-border inline-flex px-2 py-1 font-mono text-[10px] font-black uppercase tracking-[0.15em] shadow-nav ${tone}`}>{label}</span>
                <p className="mt-4 font-display text-4xl leading-none">{value}</p>
                <p className="mt-3 text-sm font-bold leading-6">{body}</p>
              </article>
            ))}
          </aside>

          <section className="brutal-border flex min-h-[640px] flex-col bg-white/70 p-3 shadow-shadow animate-message-in sm:p-5">
            <div className="flex items-center justify-between gap-4 border-b-[3px] border-border bg-paper p-4">
              <div>
                <p className="label-mono text-aizome">Today’s notebook chat</p>
                <h2 className="font-display text-3xl">Particle review</h2>
              </div>
              <div className="brutal-border rotate-3 bg-correction px-3 py-2 font-mono text-xs font-black uppercase tracking-[0.16em] text-paper shadow-nav">Due now</div>
            </div>

            <div className="notebook-panel flex flex-1 flex-col justify-end gap-4 p-4">
              {messages.map(([role, text], index) => (
                <Bubble key={`${role}-${index}`} name={role === 'user' ? 'You' : '先生'} side={role} jp={role === 'assistant'}>{text}</Bubble>
              ))}
              <div className="brutal-border bg-white p-3 shadow-shadow">
                <p className="label-mono text-correction">Correction mark</p>
                <p className="mt-2 font-bold leading-6">Great. Next, explain why 「に」 is used for direction.</p>
              </div>
            </div>

            <div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto]">
              <input className="field-brutal" value="場所は『で』、方向は『に』です。" readOnly />
              <button type="button" className="brutal-border bg-correction px-5 py-3 font-mono text-sm font-black uppercase tracking-[0.12em] text-paper shadow-shadow transition-all hover:translate-x-boxShadowX hover:translate-y-boxShadowY hover:shadow-none">Send</button>
            </div>
          </section>
        </div>
      </section>
    </main>
  );
}

function Bubble({ children, jp = false, name, side = 'assistant' }) {
  const isUser = side === 'user';
  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}>
      <article className={`brutal-border max-w-[88%] px-4 py-3 shadow-shadow ${isUser ? 'bg-aizome text-paper' : 'bg-paper text-ink'}`}>
        <p className="font-mono text-[10px] font-black uppercase tracking-[0.18em] opacity-75">{name}</p>
        <p className={`mt-1 whitespace-pre-wrap ${jp ? 'font-jp text-lg font-bold leading-8' : 'font-bold leading-7'}`}>{children}</p>
      </article>
    </div>
  );
}

function Badge({ children, tone = 'mustard' }) {
  const tones = { mustard: 'bg-mustard text-ink', moss: 'bg-moss text-paper' };
  return <span className={`brutal-border inline-flex px-3 py-1.5 font-mono text-xs font-black uppercase tracking-[0.16em] shadow-nav ${tones[tone]}`}>{children}</span>;
}

function CTA({ children, href, tone }) {
  const tones = { primary: 'bg-correction text-paper', neutral: 'bg-white text-ink hover:bg-mustard' };
  return <Link href={href} className={`brutal-border inline-flex items-center justify-center px-5 py-4 font-mono text-sm font-black uppercase tracking-[0.12em] shadow-shadow transition-all hover:translate-x-boxShadowX hover:translate-y-boxShadowY hover:shadow-none ${tones[tone]}`}>{children}</Link>;
}
