'use client';

import Link from 'next/link';
import { useState } from 'react';

const checkpoints = [
  ['あ', 'Kana warmup', 'Complete'],
  ['N5', 'Particle review', 'Today'],
  ['会', 'Kaiwa café', 'Next'],
  ['点', 'Score memory', 'Saved'],
];

const conversations = {
  Café: [
    ['assistant', 'いらっしゃいませ。ご注文は何ですか？'],
    ['user', 'アイスコーヒーを一つください。'],
    ['assistant', 'はい。サイズはどうしますか？'],
    ['user', 'Mサイズでお願いします。'],
  ],
  School: [
    ['assistant', '今日は学校で何を勉強しましたか？'],
    ['user', '日本語を勉強しました。'],
    ['assistant', 'いいですね。日本語の何が好きですか？'],
    ['user', '会話が好きです。'],
  ],
  Directions: [
    ['assistant', 'すみません、駅はどこですか？'],
    ['user', '駅は右です。'],
    ['assistant', '自然に言うなら「駅は右にあります」です。もう一度言ってみましょう。'],
    ['user', '駅は右にあります。'],
  ],
};

const topics = Object.keys(conversations);

export default function StampRallyVariant() {
  const [topic, setTopic] = useState('Café');

  return (
    <main className="screen-shell pb-28">
      <section className="min-h-[calc(100vh-8rem)] py-6">
        <div className="mx-auto max-w-5xl text-center animate-panel-in">
          <div className="mb-5 flex justify-center">
            <div className="brutal-border rotate-[-3deg] bg-mustard px-4 py-2 font-mono text-xs font-black uppercase tracking-[0.16em] shadow-shadow">
              Chat rally direction
            </div>
          </div>
          <h1 className="font-display text-5xl leading-[0.95] tracking-tight sm:text-7xl lg:text-8xl">
            Every chat earns a stamp.
          </h1>
          <p className="mx-auto mt-5 max-w-2xl text-lg font-bold leading-8">
            This version keeps the big original-style chat but frames each conversation as a visible study milestone.
          </p>
        </div>

        <div className="mt-10 grid gap-6 xl:grid-cols-[0.92fr_1.08fr] xl:items-stretch">
          <section className="brutal-border bg-white p-4 shadow-shadow sm:p-6">
            <div className="flex flex-col gap-3 border-b-[3px] border-border pb-4 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <p className="label-mono text-correction">Today’s route</p>
                <h2 className="font-display text-4xl">N5 stamp board</h2>
              </div>
              <span className="brutal-border bg-moss px-3 py-2 font-mono text-xs font-black uppercase tracking-[0.16em] text-paper shadow-nav">3 / 4 active</span>
            </div>

            <div className="mt-6 grid gap-4 sm:grid-cols-2">
              {checkpoints.map(([mark, title, status], index) => (
                <article key={title} className={`brutal-border relative bg-paper p-4 shadow-shadow ${index === 2 ? 'bg-mustard' : ''}`}>
                  <div className={`grid h-20 w-20 place-items-center rounded-full border-[4px] border-border font-display text-2xl shadow-nav ${index === 1 ? 'bg-correction text-paper' : index === 2 ? 'bg-white text-correction' : 'bg-white text-ink'}`}>
                    {mark}
                  </div>
                  <h3 className="mt-4 font-display text-2xl">{title}</h3>
                  <p className="mt-2 font-mono text-[10px] font-black uppercase tracking-[0.16em] text-aizome">{status}</p>
                </article>
              ))}
            </div>

            <div className="mt-5 flex flex-wrap gap-2">
              {topics.map((item) => (
                <button
                  key={item}
                  type="button"
                  onClick={() => setTopic(item)}
                  className={`brutal-border px-3 py-2 font-mono text-xs font-black uppercase tracking-[0.14em] shadow-nav transition-all hover:translate-x-[3px] hover:translate-y-[3px] hover:shadow-none ${topic === item ? 'bg-correction text-paper' : 'bg-white text-ink hover:bg-mustard'}`}
                >
                  {item}
                </button>
              ))}
            </div>
          </section>

          <aside className="brutal-border flex min-h-[640px] flex-col bg-white/70 p-3 shadow-shadow sm:p-5">
            <div className="flex items-center justify-between gap-4 border-b-[3px] border-border bg-paper p-4">
              <div>
                <p className="label-mono text-aizome">Selected chat route</p>
                <h2 className="font-display text-4xl">{topic} practice</h2>
              </div>
              <img src="/icon.png" alt="" className="brutal-border h-14 w-14 rotate-6 object-cover shadow-nav" />
            </div>

            <div className="notebook-panel flex flex-1 flex-col justify-end gap-4 p-4">
              {conversations[topic].map(([role, text], index) => (
                <Bubble key={`${topic}-${role}-${index}`} name={role === 'user' ? 'You' : '先生'} side={role} jp={role === 'assistant'}>{text}</Bubble>
              ))}
              <div className="brutal-border bg-white p-4 shadow-shadow">
                <p className="label-mono text-correction">Stamp earned after</p>
                <p className="mt-2 font-bold leading-6">Use one complete sentence and answer the follow-up question.</p>
              </div>
            </div>

            <div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto]">
              <input className="field-brutal" value={topic === 'Directions' ? '駅は右にあります。' : 'もう一度お願いします。'} readOnly />
              <Link href="/chat/sensei" className="brutal-border inline-flex justify-center bg-correction px-5 py-3 font-mono text-sm font-black uppercase tracking-[0.12em] text-paper shadow-shadow transition-all hover:translate-x-boxShadowX hover:translate-y-boxShadowY hover:shadow-none">Chat</Link>
            </div>
          </aside>
        </div>
      </section>
    </main>
  );
}

function Bubble({ children, jp = false, name, side = 'assistant' }) {
  const isUser = side === 'user';
  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}>
      <article className={`brutal-border max-w-[88%] px-4 py-3 shadow-shadow ${isUser ? 'bg-aizome text-paper' : 'bg-paper text-ink'}`}>
        <p className="font-mono text-[10px] font-black uppercase tracking-[0.18em] opacity-75">{name}</p>
        <p className={`mt-1 whitespace-pre-wrap ${jp ? 'font-jp text-lg font-bold leading-8' : 'font-bold leading-7'}`}>{children}</p>
      </article>
    </div>
  );
}
